import sys

data = sys.stdin.read().split()
n, k = int(data[0]), int(data[1])
adj = [[] for _ in range(n)]
for i in range(n - 1):
    a, b = int(data[2 + 2 * i]), int(data[3 + 2 * i])
    adj[a].append(b)
    adj[b].append(a)
sys.setrecursionlimit(10000)

def height(v, par):
    best = 0
    for u in adj[v]:
        if u != par:
            best = max(best, height(u, v))
    return best + 1

score = [0] * n
def fill(v, par):
    score[v] = height(v, par)
    for u in adj[v]:
        if u != par:
            fill(u, v)
fill(0, -1)

def counted(v, par, deleted):
    best = 0
    for u in adj[v]:
        if u != par:
            best = max(best, counted(u, v, deleted))
    return best + (0 if (deleted >> v) & 1 else 1)

ans = None
for mask in range(1 << n):
    if counted(0, -1, mask) <= k:
        size = bin(mask).count('1')
        sc = sum(score[v] for v in range(n) if (mask >> v) & 1)
        if ans is None or (size, sc) < ans:
            ans = (size, sc)
print(ans[0], ans[1])

