def gen(rng):
    def fmt(n, k, parents):
        labels = list(range(1, n))
        rng.shuffle(labels)
        lab = [0] + labels
        edges = []
        for i in range(1, n):
            a, b = lab[parents[i]], lab[i]
            if rng.random() < 0.5:
                a, b = b, a
            edges.append(f'{a} {b}')
        rng.shuffle(edges)
        return f'{n} {k}' + ''.join('\n' + e for e in edges)

    def shape(kind, n):
        par = [0] * n
        for i in range(1, n):
            if kind == 'rand':
                par[i] = rng.randint(0, i - 1)
            elif kind == 'path':
                par[i] = i - 1
            elif kind == 'deep':
                par[i] = rng.randint(max(0, i - 3), i - 1)
            elif kind == 'star':
                par[i] = 0
            elif kind == 'bin':
                par[i] = (i - 1) // 2
            elif kind == 'cat':
                s = max(1, n // 2)
                par[i] = i - 1 if i < s else rng.randint(0, s - 1)
            elif kind == 'broom':
                s = max(1, n // 2)
                par[i] = i - 1 if i < s else s - 1
        return par

    kinds = ['rand', 'path', 'deep', 'star', 'bin', 'cat', 'broom']
    tests = ['1 1', '1 1\n'.strip(), '2 1\n0 1', '2 2\n1 0', '5 3\n0 1\n1 2\n2 3\n3 4',
             '7 2\n0 1\n0 2\n1 3\n1 4\n2 5\n2 6', '7 2\n0 1\n0 2\n0 3\n3 4\n4 5\n5 6', '6 3\n0 1\n1 2\n2 3\n0 4\n4 5']
    for _ in range(40):
        n = rng.randint(2, 12)
        kind = rng.choice(kinds)
        tests.append(fmt(n, rng.randint(1, n), shape(kind, n)))
    for kind in kinds:
        for n in (9, 12):
            tests.append(fmt(n, rng.randint(1, max(1, n // 2)), shape(kind, n)))
    n = 2000
    tests.append(fmt(n, 1000, shape('path', n)))
    tests.append(fmt(n, 1, shape('path', n)))
    tests.append(fmt(n, 60, shape('deep', n)))
    tests.append(fmt(n, 500, shape('cat', n)))
    tests.append(fmt(n, 400, shape('broom', n)))
    tests.append(fmt(n, 5, shape('bin', n)))
    tests.append(fmt(n, 5, shape('rand', n)))
    tests.append(fmt(n, 500, shape('deep', n)))
    return tests

